{
    uint32_t lo = 0;
    uint32_t hi = (uint32_t)(sizeof gw_mex_bridge_guest_tbl /
                            sizeof gw_mex_bridge_guest_tbl[0]);
    if (guest_addr < 0x803B7280u || guest_addr >= 0x804DEA9Cu) {
        return 0;
    }
    while (lo < hi) {
        uint32_t mid = lo + (hi - lo) / 2;
        const gw_mex_bridge_grun *r = &gw_mex_bridge_guest_tbl[mid];
        if (guest_addr < r->lo) { hi = mid; continue; }
        if (guest_addr >= r->hi) { lo = mid + 1; continue; }
        return r->native + (guest_addr - r->lo);
    }
    return 0;
}

